document.addEventListener('click',handleClick);
document.addEventListener('submit',submitHandler);
document.addEventListener('input',e=>{if(e.target.id==='faq-search'){ui.faqSearch=e.target.value.slice(0,100);faqRefresh();}});
document.addEventListener('change',e=>{if(e.target.closest('#personal-plan-form')){const form=e.target.closest('#personal-plan-form');if(e.target.name==='focus'&&e.target.checked&&new FormData(form).getAll('focus').length>2){e.target.checked=false;notify('Escolha no máximo duas prioridades.');}refreshPersonalPreview();}if(e.target.id==='mod-kind')syncModalityForm(true);if(e.target.id==='mod-duration')syncModalityForm(false);if(e.target.id==='mod-cardio')e.target.dataset.auto='no';handleInput(e);if(e.target.id==='measure-date')populateBodyMeasurementDate(e.target.value);if(e.target.id==='import-input')importFile(e.target.files?.[0]);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(restAlertVisible){closeRestAlert();ui.restSeconds=60;render();}else closeModal();}});
document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>{setNav(b.dataset.nav);if(b.dataset.nav==='workouts'&&!screenWakeRequested){screenWakeRequested=true;requestScreenWake(true);}}));
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){pauseSessionTimer();}else{if(screenWakeRequested&&ui.page==='workouts')requestScreenWake(true);doTick();if(restAlertVisible)playRestAlarm();}});
